hsgLesson(document.getElementById("gate-l14"),"quiz14");
const PR14=[{label:"Ví dụ: lower_bound, upper_bound và đếm trong khoảng",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> a = {8, 3, 1, 5, 3};\n    sort(a.begin(), a.end());                       // 1 3 3 5 8\n    int lb = lower_bound(a.begin(), a.end(), 3) - a.begin();\n    int ub = upper_bound(a.begin(), a.end(), 3) - a.begin();\n    cout << lb << \" \" << ub << \"\\n\";                  // 1 3\n    // số phần tử trong [2, 6]\n    int dem = upper_bound(a.begin(), a.end(), 6) - lower_bound(a.begin(), a.end(), 2);\n    cout << dem << \"\\n\";                              // 3\n    int k = lower_bound(a.begin(), a.end(), 100) - a.begin();\n    cout << k << \"\\n\";                                // 5 = n: không có phần tử >= 100\n    return 0;\n}",viz:[{type:"cells",of:"a"}]},{label:"Ví dụ: Đếm cặp có tổng ≤ S",input:"5 7\n4 1 6 2 3",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CAPTONG.INP\", \"r\")) {\n        freopen(\"CAPTONG.INP\", \"r\", stdin);\n        freopen(\"CAPTONG.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long S;\n    cin >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long dem = 0;\n    for (int i = 0; i < n; i++) {\n        // các j > i có a[j] <= S - a[i]\n        int k = upper_bound(a.begin() + i + 1, a.end(), S - a[i]) - a.begin();\n        dem += k - (i + 1);\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","k"]},{type:"vars",names:["dem"]}]},{label:"Ví dụ: Phần tử lớn nhất không vượt x",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<long long> t = {6, 15, 35, 77, 143};      // tích các cặp nguyên tố liên tiếp\n    vector<long long> q = {20, 6, 5, 1000};\n    for (long long n : q) {\n        int k = upper_bound(t.begin(), t.end(), n) - t.begin();\n        if (k == 0) cout << \"khong co\\n\";\n        else cout << t[k - 1] << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"t"},{type:"vars",names:["n","k"]}]}];
