makeEx2(document.getElementById("ex-l14"),sim14,[{t:"Đếm trong khoảng",d:"File DEMKHOANG.INP: dòng 1 là n (1 ≤ n ≤ 10^5); dòng 2 là n số nguyên (|aᵢ| ≤ 10^9); dòng 3 là q (1 ≤ q ≤ 10^5); q dòng sau mỗi dòng x, y (x ≤ y). Ghi vào DEMKHOANG.OUT q dòng: số phần tử của dãy nằm trong đoạn [x, y].",tests:[{in:"5\n8 3 1 5 3\n3\n2 6\n3 3\n9 100",out:"3\n2\n0"},{in:"1\n5\n2\n5 5\n-10 4",out:"1\n0"},{in:"4\n-1000000000 0 0 1000000000\n2\n-1000000000 1000000000\n0 0",out:"4\n2"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DEMKHOANG.INP\", \"r\")) {\n        freopen(\"DEMKHOANG.INP\", \"r\", stdin);\n        freopen(\"DEMKHOANG.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (auto& x : a) cin >> x;\n    int q;\n    cin >> q;\n    while (q--) {\n        int x, y;\n        cin >> x >> y;\n        int dem = 0;\n        for (int v : a)\n            if (x <= v && v <= y) dem++;\n        cout << dem << \"\\n\";\n    }\n    return 0;\n}",file:"DEMKHOANG",perf:{gen:n=>{const q=n;let s=n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%100003).join(" ")+"\n"+q+"\n";for(let i=0;i<q;i++){const x=(i*313)%100003;s+=x+" "+(x+(i*97)%5000)+"\n"}return s},ns:[200,800,3200],need:"nlogn",limit:n=>Math.round(80*n*Math.log2(n))+500,why:"Duyệt cả dãy cho mỗi truy vấn là O(n · q). Sắp xếp một lần rồi mỗi truy vấn hai lần tìm kiếm nhị phân: O((n + q) log n)."}},{t:"Đếm cặp",d:"File CAPTONG.INP: dòng 1 là n, S (2 ≤ n ≤ 10^5, |S| ≤ 2·10^9); dòng 2 là n số nguyên (|aᵢ| ≤ 10^9). Ghi vào CAPTONG.OUT số cặp chỉ số i < j có aᵢ + aⱼ ≤ S.",tests:[{in:"5 7\n4 1 6 2 3",out:"7"},{in:"2 0\n1 -1",out:"1"},{in:"3 -1\n0 0 0",out:"0"},{in:"4 2000000000\n1000000000 1000000000 1000000000 1000000000",out:"6"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CAPTONG.INP\", \"r\")) {\n        freopen(\"CAPTONG.INP\", \"r\", stdin);\n        freopen(\"CAPTONG.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long S;\n    cin >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    long long dem = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = i + 1; j < n; j++)\n            if (a[i] + a[j] <= S) dem++;\n    cout << dem << \"\\n\";\n    return 0;\n}",file:"CAPTONG",perf:{gen:n=>n+" "+(50000)+"\n"+Array.from({length:n},(_,i)=>(i*7919)%100003).join(" "),ns:[200,800,3200],need:"nlogn",limit:n=>Math.round(80*n*Math.log2(n))+500,why:"Hai vòng lặp là O(n²). Sau khi sắp xếp, mỗi i chỉ cần một lần upper_bound."}},{t:"Xếp gạch (thu nhỏ)",d:"File GACH.INP: dòng 1 là T (1 ≤ T ≤ 10^4); T dòng sau mỗi dòng một số n (1 ≤ n ≤ 10^6). Với mỗi n, chọn hai số nguyên tố liên tiếp p < q (ví dụ 2 và 3, 3 và 5, 5 và 7…) có p · q ≤ n và số thừa n − p · q nhỏ nhất. Ghi vào GACH.OUT T dòng: số thừa đó, hoặc -1 nếu không có cặp nào (n < 6).",tests:[{in:"3\n20\n25\n2021",out:"5\n10\n0"},{in:"2\n5\n6",out:"-1\n0"},{in:"1\n1000000",out:"11973"},{in:"2\n35\n76",out:"0\n41"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"GACH.INP\", \"r\")) {\n        freopen(\"GACH.INP\", \"r\", stdin);\n        freopen(\"GACH.OUT\", \"w\", stdout);\n    }\n    // 1. sàng (hoặc thử chia) các số nguyên tố tới 1000\n    // 2. tạo dãy tích hai số nguyên tố liên tiếp (tự tăng dần)\n    // 3. với mỗi n: upper_bound rồi lùi một ô\n    return 0;\n}",file:"GACH",perf:{gen:n=>{let s=n+"\n";for(let i=0;i<n;i++)s+=(1+(i*7919)%1000000)+"\n";return s},ns:[500,2000,8000],need:"n",limit:n=>60*n+120000,why:"Thử lại mọi cặp số nguyên tố cho mỗi truy vấn tốn tới khoảng 170 bước mỗi truy vấn. Tạo dãy tích một lần, mỗi truy vấn chỉ một lần tìm kiếm nhị phân."}}]);

